[
  {
    "question": "Which term refers to the collection of metadata that describes the structure of a database in a DBMS?",
    "options": {
      "A": "Instance",
      "B": "Schema",
      "C": "Catalog",
      "D": "Abstraction"
    },
    "correct_answer": "C",
    "explanation": "The catalog stores metadata about the database objects (tables, columns, constraints) and therefore is the collection of metadata that defines the database structure.",
    "difficulty": "Medium"
  },
  {
    "question": "In the typical DBMS architecture, which component is chiefly responsible for guaranteeing the atomicity and durability properties of transactions?",
    "options": {
      "A": "Query processor",
      "B": "Storage manager",
      "C": "Transaction manager",
      "D": "Authorization manager"
    },
    "correct_answer": "C",
    "explanation": "The transaction manager handles transaction scheduling, logging, and recovery, ensuring atomicity (all‑or‑nothing) and durability (changes survive crashes).",
    "difficulty": "Medium"
  },
  {
    "question": "Which statement correctly distinguishes a DBMS from a traditional file‑based system?",
    "options": {
      "A": "A DBMS stores data in a single flat file, while a file system uses tables.",
      "B": "A DBMS provides data independence, whereas a file system does not.",
      "C": "A file system enforces referential integrity, while a DBMS does not.",
      "D": "A DBMS requires manual indexing, while a file system indexes automatically."
    },
    "correct_answer": "B",
    "explanation": "One of the core advantages of a DBMS is data independence—the ability to change the physical storage without affecting application programs—something file systems lack.",
    "difficulty": "Medium"
  },
  {
    "question": "What result does the relational algebra expression σ_{title='Database Management Systems'}(Course) produce?",
    "options": {
      "A": "All attributes of the Course relation.",
      "B": "All tuples of Course where the title equals 'Database Management Systems'.",
      "C": "The count of courses titled 'Database Management Systems'.",
      "D": "The schema of Course filtered by the title attribute."
    },
    "correct_answer": "B",
    "explanation": "The selection operator σ selects those rows (tuples) that satisfy the predicate; here it returns every Course tuple whose title is 'Database Management Systems'.",
    "difficulty": "Medium"
  },
  {
    "question": "Which of the following exemplifies data abstraction in a DBMS?",
    "options": {
      "A": "Storing raw bytes directly on disk.",
      "B": "Defining a view that hides the underlying base tables.",
      "C": "Specifying a primary‑key constraint on a table.",
      "D": "Writing a SELECT statement with a WHERE clause."
    },
    "correct_answer": "B",
    "explanation": "A view provides a logical layer that abstracts away the physical tables and their details, presenting a simplified interface to users.",
    "difficulty": "Medium"
  }
]
